import type { ChartData } from 'chart.js';
import { Skeleton } from 'components';
import { Doughnut } from 'components/Chart';

import type { PortfolioPieChartData, PortfolioPieSlice } from '../../types';
import {
  StyledPortfolioPieChartInner,
  StyledPortfolioPieChartPlot,
  StyledPortfolioPieChartRoot,
  StyledPortfolioPieChartTitle,
  StyledPortfolioPieLegend,
  StyledPortfolioPieLegendItem,
  StyledPortfolioPieLegendSwatch,
} from './PortfolioPieChart.styles';
import { getPortfolioPieSliceFallbackColor } from './portfolioPieSliceFallbackColors';

export interface PortfolioPieChartProps {
  chartId: PortfolioPieChartData['id'];
  title: string;
  slices: PortfolioPieSlice[];
  loading?: boolean;
  dataTestId?: string;
}

const LegendItem = ({ color, label }: { color: string; label: string }) => (
  <StyledPortfolioPieLegendItem>
    <StyledPortfolioPieLegendSwatch style={{ backgroundColor: color }} />
    {label}
  </StyledPortfolioPieLegendItem>
);

export const PortfolioPieChart: React.FC<PortfolioPieChartProps> = ({
  chartId,
  title,
  slices,
  loading,
  dataTestId,
}) => {
  const sliceColor = (slice: PortfolioPieSlice, index: number) =>
    slice.color ?? getPortfolioPieSliceFallbackColor(chartId, index);

  const chartData: ChartData<'doughnut'> = {
    labels: slices.map((s) => s.label),
    datasets: [
      {
        data: slices.map((s) => s.percentage),
        backgroundColor: slices.map((s, i) => sliceColor(s, i)),
        borderColor: slices.map((s) => s.borderColor ?? '#ffffff'),
        borderWidth: slices.map((s) => s.borderWidth ?? 0.5),
      },
    ],
  };

  if (loading) {
    return (
      <StyledPortfolioPieChartRoot data-testid={dataTestId}>
        <Skeleton
          height="280px"
          width="100%"
          length={1}
          borderRadius="medium"
        />
      </StyledPortfolioPieChartRoot>
    );
  }

  if (!slices.length) {
    return (
      <StyledPortfolioPieChartRoot data-testid={dataTestId}>
        <Skeleton
          height="280px"
          width="100%"
          length={1}
          borderRadius="medium"
        />
      </StyledPortfolioPieChartRoot>
    );
  }

  return (
    <StyledPortfolioPieChartRoot data-testid={dataTestId}>
      <StyledPortfolioPieChartTitle>
        <h3>{title}</h3>
      </StyledPortfolioPieChartTitle>
      <StyledPortfolioPieChartInner>
        <StyledPortfolioPieLegend>
          {slices.map((s, i) => (
            <LegendItem
              key={`${s.label}-${i}`}
              color={sliceColor(s, i)}
              label={s.label}
            />
          ))}
        </StyledPortfolioPieLegend>
        <StyledPortfolioPieChartPlot>
          <Doughnut
            data={chartData}
            height={263}
            width={306}
            dataTestId={dataTestId ? `${dataTestId}-doughnut` : undefined}
          />
        </StyledPortfolioPieChartPlot>
      </StyledPortfolioPieChartInner>
    </StyledPortfolioPieChartRoot>
  );
};
